import { simpleApiKey } from '@opensteward/shared'
/**
 * VirtueMart adapter for the ecommerce vertical.
 *
 * VirtueMart is a Joomla CMS ecommerce extension. It documents NO REST or
 * JSON web-service API. Its "VM API" page (https://docs.virtuemart.net/vm-api)
 * says: "The VirtueMart API documentation is generated by the tool Doxygen."
 * That Doxygen reference (https://api.virtuemart.net/files.html) describes the
 * PHP classes. Its file list names the site views askquestion, cart, category,
 * invoice, manufacturer, orders, pdf, productdetails, recommend, user, vendor,
 * virtuemart and vmplg: there is no `products`, `categories` or `users` view,
 * and `orders` ships only `view.html.php` (the logged-in shopper's own order
 * page), so `index.php?option=com_virtuemart&view=<view>&format=json` has no
 * JSON list to return for any of them.
 *
 * Every read method therefore refuses with 501 NOT_SUPPORTED before sending
 * anything. `cancelOrder` (a write, out of scope for the read rebuild) still
 * POSTs to the undocumented `view=orders` and is recorded as fabricated.
 *
 * Credentials (unchanged): `accessToken` and `extra.baseUrl`. VirtueMart
 * documents no API token; the Joomla site frontend authenticates by session.
 *
 * Slug: `virtuemart`
 *
 * ── Resource coverage ──────────────────────────────────────────────────────
 * Unavailable: product, order, customer, collection, inventory — no documented
 *   list or read endpoint (see above)
 * Unavailable: location    — no warehouse/location concept in VirtueMart core
 * Unavailable: fulfillment — no documented fulfillment endpoint
 * Unavailable: refund      — no documented refund endpoint
 * Unavailable: transaction — no documented transaction endpoint
 * Unavailable: discount    — no documented discount/coupon endpoint
 */

import type { Credentials, QueryParams } from '@opensteward/shared'
import type { EcommerceAdapter } from '../../adapter/interface'
import type { Product } from '../../schema/product'
import type { InventoryLevel } from '../../schema/inventory'
import type { Customer } from '../../schema/customer'
import type { Order } from '../../schema/order'
import type { Collection } from '../../schema/collection'

import {
  getAuthUrl as vmGetAuthUrl,
  exchangeCode as vmExchangeCode,
  refreshCredentials as vmRefreshCredentials,
} from './auth'
import { VirtueMartClient } from './client'
import { VM_STATUS_CANCELLED } from './constants'
import { transformOrder, type VirtueMartOrder } from './transform/order'

const SIMPLE_API_KEY_FORM = simpleApiKey()

/**
 * Why VirtueMart has nothing to read: its only first-party API reference is a
 * Doxygen dump of the PHP code, and the site component has no JSON view for
 * this resource.
 */
const NO_API =
  'VirtueMart documents no REST/JSON API ("The VirtueMart API documentation is generated by ' +
  'the tool Doxygen." — https://docs.virtuemart.net/vm-api)'

/** A deliberate refusal, thrown before any request is sent. */
function notSupported(message: string): Error {
  return Object.assign(new Error(message), { statusCode: 501, code: 'NOT_SUPPORTED' })
}

export class VirtueMartAdapter implements EcommerceAdapter {
  // Connect Link support — single API-key form.

  credentialFields = SIMPLE_API_KEY_FORM.credentialFields

  exchangeCredentials = SIMPLE_API_KEY_FORM.exchangeCredentials

  readonly platform = 'virtuemart'
  readonly version = '0.1.0'

  // ── Auth ──────────────────────────────────────────────────────────────────

  getAuthUrl(state: string): string {
    return vmGetAuthUrl(state)
  }

  async exchangeCode(code: string, redirectUri: string): Promise<Credentials> {
    return vmExchangeCode(code, redirectUri)
  }

  async refreshCredentials(credentials: Credentials): Promise<Credentials> {
    return vmRefreshCredentials(credentials)
  }

  // ── Products ──────────────────────────────────────────────────────────────

  async listProducts(_credentials: Credentials, _params: QueryParams): Promise<Product[]> {
    throw notSupported(
      `VirtueMart cannot list products: the site component has no "products" view. ${NO_API}`,
    )
  }

  async getProduct(_credentials: Credentials, _id: string): Promise<Product> {
    throw notSupported(
      `VirtueMart cannot read a product: the site component has no "products" view. ${NO_API}`,
    )
  }

  // ── Orders ────────────────────────────────────────────────────────────────

  async listOrders(_credentials: Credentials, _params: QueryParams): Promise<Order[]> {
    throw notSupported(
      'VirtueMart cannot list orders: the site "orders" view ships only view.html.php ' +
        `(the logged-in shopper's own orders page), with no JSON view. ${NO_API}`,
    )
  }

  async getOrder(_credentials: Credentials, _id: string): Promise<Order> {
    throw notSupported(
      'VirtueMart cannot read an order: the site "orders" view ships only view.html.php, ' +
        `with no JSON view. ${NO_API}`,
    )
  }

  async cancelOrder(
    credentials: Credentials,
    id: string,
    _data?: { reason?: string },
  ): Promise<Order> {
    const client = new VirtueMartClient(credentials)
    // Out of scope for the read rebuild: this view has no documented write API.
    const raw = await client.post<VirtueMartOrder>('orders', {
      virtuemart_order_id: id,
      order_status: VM_STATUS_CANCELLED,
    })
    return transformOrder(raw)
  }

  // ── Customers ─────────────────────────────────────────────────────────────

  async listCustomers(_credentials: Credentials, _params: QueryParams): Promise<Customer[]> {
    throw notSupported(
      `VirtueMart cannot list customers: the site component has no "users" view. ${NO_API}`,
    )
  }

  async getCustomer(_credentials: Credentials, _id: string): Promise<Customer> {
    throw notSupported(
      `VirtueMart cannot read a customer: the site component has no "users" view. ${NO_API}`,
    )
  }

  // ── Collections ───────────────────────────────────────────────────────────

  async listCollections(_credentials: Credentials, _params: QueryParams): Promise<Collection[]> {
    throw notSupported(
      `VirtueMart cannot list collections: the site component has no "categories" view. ${NO_API}`,
    )
  }

  async getCollection(_credentials: Credentials, _id: string): Promise<Collection> {
    throw notSupported(
      'VirtueMart cannot read a collection: the site component has no "categories" view. ' + NO_API,
    )
  }

  // ── Inventory ─────────────────────────────────────────────────────────────

  async listInventoryLevels(
    _credentials: Credentials,
    _params: QueryParams,
  ): Promise<InventoryLevel[]> {
    throw notSupported(
      'VirtueMart cannot list inventory levels: the site component has no "products" view ' +
        `to read stock from. ${NO_API}`,
    )
  }

  async getInventoryLevel(_credentials: Credentials, _id: string): Promise<InventoryLevel> {
    throw notSupported(
      'VirtueMart cannot read an inventory level: the site component has no "products" view ' +
        `to read stock from. ${NO_API}`,
    )
  }
}
